public void initFromGUPVendPriceAdmTrans(GUPVendPriceAdmTrans _gupVendPriceAdmTrans)
{
    this.AccountCode     = _gupVendPriceAdmTrans.AccountCode;
    this.AccountRelation = _gupVendPriceAdmTrans.AccountRelation;
    this.ItemNum         = _gupVendPriceAdmTrans.ItemNum;
    this.NameSim         = _gupVendPriceAdmTrans.NameSim;
    this.UnitId          = _gupVendPriceAdmTrans.UnitId;
    this.Currency        = _gupVendPriceAdmTrans.Currency;
    this.Amount          = _gupVendPriceAdmTrans.Amount;
    this.PriceUnit       = _gupVendPriceAdmTrans.PriceUnit;
    this.Markup          = _gupVendPriceAdmTrans.Markup;
    this.JournalNum      = _gupVendPriceAdmTrans.JournalNum;
    this.InventDimId     = _gupVendPriceAdmTrans.InventDimId;
    this.LineNum         = GUPVendPriceAdmTrans::lastLineNum(_gupVendPriceAdmTrans.JournalNum) + 1;
}

public void initFromGUPVendPriceAdmTable(GUPVendPriceAdmTable _gupVendPriceAdmTable)
{
    this.JournalNum         = _gupVendPriceAdmTable.JournalNum;
    this.AccountCode        = _gupVendPriceAdmTable.AccountCode;
    this.AccountRelation    = _gupVendPriceAdmTable.AccountRelation;
    this.FromDate           = _gupVendPriceAdmTable.FromDate;
    this.ToDate             = _gupVendPriceAdmTable.ToDate;
    this.LineNum         = GUPVendPriceAdmTrans::lastLineNum(_gupVendPriceAdmTable.JournalNum) + 1;

    if (_gupVendPriceAdmTable.InventSiteId)
    {
        InventDim inventDim;

        inventDim.InventSiteId = _gupVendPriceAdmTable.InventSiteId;

        this.InventDimId = InventDim::findOrCreate(inventDim).inventDimId;
    }
}

public InventDim inventDim(boolean  update = false)
{
    return InventDim::find(this.InventDimId, update);
}

    public void initValue()
    {
        super();

        this.PriceUnit = 1;
	}

public void preWrite()
{
    if (this.AccountCode == TableGroupAll::All)
    {
        this.AccountRelation = '';
    }
}

public void  insert()
{
    this.preWrite();

    super();
}

public void update()
{
    this.preWrite();

    super();
}

public TableExtension getExtension()
{
    return SysTableExtension::construct();
}

public container getDefaultingDependencies()
{
    return [[fieldnum(GUPVendPriceAdmTrans, AccountRelation), [fieldnum(GUPVendPriceAdmTrans, AccountCode)]],
            [fieldnum(GUPVendPriceAdmTrans, UnitId), [fieldnum(GUPVendPriceAdmTrans, ItemNum)]],
            [fieldnum(GUPVendPriceAdmTrans, Currency), [fieldnum(GUPVendPriceAdmTrans, AccountRelation)]]
           ];
}

public void defaultField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldnum(GUPVendPriceAdmTrans, AccountRelation):
            this.defaultAccountRelation();
            break;

        case fieldnum(GUPVendPriceAdmTrans, UnitId):
            this.initFromItemCode();
            break;

        case fieldnum(GUPVendPriceAdmTrans, Currency):
            this.initFromAccountCode();
            break;
    }
}

private void defaultAccountRelation()
{
    if (this.AccountCode == TableGroupAll::All)
    {
        this.AccountRelation = '';
    }
}

public void initFromItemCode()
{
    InventTable inventTable;

    if (this.UnitId && this.ItemNum == this.orig().ItemNum)
    {
        return;
    }

    inventTable = InventTable::find(this.ItemNum);

    this.UnitId = inventTable.purchUnitId();
}

public void initFromAccountCode()
{
    VendTable   vendTable;

    if (this.AccountCode != TableGroupAll::Table)
    {
        return;
    }

    vendTable = VendTable::find(this.AccountRelation);
    this.Currency = vendTable.Currency;
}

public boolean validateField(FieldId  fieldId)
{
    boolean ok = super(fieldId);

    switch (fieldId)
    {
        case (fieldNum(GUPVendPriceAdmTrans, AccountRelation)) :   
            ok = this.checkAccountRelation();
            break;
    }

    return ok;
}

public boolean validateWrite()
{
    boolean ok = super();

    ok = this.checkProductDimensions() && ok;
    ok = this.checkAccountRelation() && ok;
    ok = this.checkCurrency() && ok;
    ok = this.checkDate() && ok;
    ok = this.checkItemId() && ok;
    ok = this.checkUnitId() && ok;
    ok = this.checkDatesOverlap() && ok;

    return ok;
}

protected boolean  checkProductDimensions()
{
    return this.inventDim().validateWriteProductDimensions(this.ItemNum, false);
}

protected boolean checkAccountRelation()
{
    boolean isOk = true;

    switch (this.AccountCode)
    {
        case TableGroupAll::Table :
            if (! this.checkAccountRelationTable())
            {
                isOk = checkFailed("@SYS4000121");
            }
            break;
        case TableGroupAll::GroupId :
            if (! this.checkVendPriceGroupExists())
            {
                isOk = checkFailed("@SYS4000121");
            }
            break;
        case TableGroupAll::All :
            if (this.AccountRelation)
            {
                isOk = checkFailed("@SYS4000121");
            }
            break;
    }

    return isOk;
}

protected boolean checkAccountRelationTable()
{
    if (this.AccountCode != TableGroupAll::Table)
    {
        return false;
    }

    return VendTable::exist(this.AccountRelation);
}

protected boolean checkVendPriceGroupExists()
{
    return GUPVendPriceGroup::exist(this.AccountRelation);
}

private boolean checkCurrency()
{
    boolean ok = true;

    if (this.Currency)
    {
        if (!Currency::exist(this.Currency))
        {
            ok = checkFailed(strFmt("@SYS1458", this.Currency));
        }
    }
    else
    {
        ok = checkFailed("@SYS23229");
    }

    return ok;
}

private boolean checkUnitId()
{
    boolean ok = true;

    if (this.UnitId && !UnitOfMeasure::find(UnitOfMeasure::unitOfMeasureIdBySymbol(this.UnitId)))
    {
        ok = checkFailed(strFmt("@SYS4108", this.UnitId));
    }

    return ok;
}

public ItemId itemId()
{
    return this.ItemNum;
}

public InventTable inventTable()
{
    return InventTable::find(this.itemId());
}

public boolean checkItemId()
{
    boolean ok = true;

    if (this.itemId())
    {
        InventTable            inventTable      = this.inventTable();
        EcoResProductValidator productValidator = EcoResProductValidator::construct(inventTable);

        if (!productValidator.isEssentialFieldValuesSet())
        {
            ok = checkFailed(strFmt("@SYS4000187", productValidator.getErrorFieldList(), this.itemId()));
        }
    }

    return ok;
}

public boolean checkDatesOverlap()
{
    GUPVendPriceAdmTrans vendPriceAdmTransOverlap;
    boolean isOk = true;

    switch (this.AccountCode)
    {
        case TableGroupAll::Table :
            select firstonly FromDate, ToDate from vendPriceAdmTransOverlap
                where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                    && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                    && (vendPriceAdmTransOverlap.AccountCode == TableGroupAll::All
                    || (vendPriceAdmTransOverlap.AccountCode == TableGroupAll::Table
                        && vendPriceAdmTransOverlap.AccountRelation == this.AccountRelation))
                    && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                        || (this.ToDate 
                            && (vendPriceAdmTransOverlap.FromDate <= this.ToDate 
                            && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                        || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                    && vendPriceAdmTransOverlap.RecId != this.RecId;

            if (!vendPriceAdmTransOverlap)
            {
                VendTable vendTable;
                GUPVendPriceGroupLink priceGroupLink;

                select firstonly FromDate, ToDate from vendPriceAdmTransOverlap
                    where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                        && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                        && vendPriceAdmTransOverlap.AccountCode == TableGroupAll::GroupId
                        && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                            || (this.ToDate
                                && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                                && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                            || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                        && vendPriceAdmTransOverlap.RecId != this.RecId
                join priceGroupLink
                    where priceGroupLink.VendPriceGroupId == vendPriceAdmTransOverlap.AccountRelation
                exists join vendTable
                    where vendTable.RecId == priceGroupLink.VendRecId
                        && vendTable.AccountNum == this.AccountRelation;
            }
            break;
        case TableGroupAll::GroupId :
            select firstonly FromDate, ToDate from vendPriceAdmTransOverlap
                where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                    && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                    && (vendPriceAdmTransOverlap.AccountCode == TableGroupAll::All
                    || (vendPriceAdmTransOverlap.AccountCode == TableGroupAll::GroupId
                        && vendPriceAdmTransOverlap.AccountRelation == this.AccountRelation))
                    && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                        || (this.ToDate
                            && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                            && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                        || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                    && vendPriceAdmTransOverlap.RecId != this.RecId;

            if (!vendPriceAdmTransOverlap)
            {
                VendTable vendTable;
                GUPVendPriceGroupLink priceGroupLink;

                select firstonly FromDate, ToDate from vendPriceAdmTransOverlap
                    where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                        && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                        && vendPriceAdmTransOverlap.AccountCode == TableGroupAll::Table
                        && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                            || (this.ToDate
                                && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                                && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                            || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                        && vendPriceAdmTransOverlap.RecId != this.RecId
                join RecId from vendTable
                    where vendTable.AccountNum == vendPriceAdmTransOverlap.AccountRelation
                exists join priceGroupLink
                    where priceGroupLink.VendRecId == vendTable.RecId
                        && priceGroupLink.VendPriceGroupId == this.AccountRelation;
            }
            break;
        case TableGroupAll::All :
            select firstonly FromDate, ToDate from vendPriceAdmTransOverlap
                where vendPriceAdmTransOverlap.ItemNum == this.ItemNum
                    && vendPriceAdmTransOverlap.InventDimId == this.InventDimId
                    && ((!this.ToDate && !vendPriceAdmTransOverlap.ToDate)
                        || (this.ToDate
                            && (vendPriceAdmTransOverlap.FromDate <= this.ToDate
                            && (!vendPriceAdmTransOverlap.ToDate || vendPriceAdmTransOverlap.ToDate >= this.FromDate)))
                        || (!this.ToDate && this.FromDate <= vendPriceAdmTransOverlap.ToDate))
                    && vendPriceAdmTransOverlap.RecId != this.RecId;
            break;
    }

    if (vendPriceAdmTransOverlap)
    {
        isOk = checkFailed(strFmt("@GlobalUnifiedPricing:GUPDatePeriodOverlapped", vendPriceAdmTransOverlap.FromDate, vendPriceAdmTransOverlap.ToDate));
    }

    return isOk;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(GUPVendPriceAdmTrans, AccountCode):
            this.AccountRelation = '';
            break;
    }
}

private boolean checkDate()
{
    boolean ok = true;

    if (this.ToDate && this.ToDate < this.FromDate)
    {
        ok = checkFailed("@SYS16982");
    }

    return ok;
}

public static GUPVendPriceAdmTrans find(RecId _recId, boolean _forupdate = false)
{
    GUPVendPriceAdmTrans GUPVendPriceAdmTrans;

    if (_recId)
    {
        GUPVendPriceAdmTrans.selectForUpdate(_forupdate);

        select firstonly GUPVendPriceAdmTrans
            where GUPVendPriceAdmTrans.RecId == _recId;
    }

    return GUPVendPriceAdmTrans;
}

static TradeLineNumber lastLineNum(GUPVendPriceJournalNum _journalNum)
{
    return (select maxof(LineNum) from GUPVendPriceAdmTrans
        index hint JourLineIdx
        where GUPVendPriceAdmTrans.JournalNum == _journalNum).LineNum;
}
